CREATE TABLE "organization" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" varchar(250) NOT NULL,
    "organization_type" varchar(60) NOT NULL,
    "municipality_id" bigint,
    CONSTRAINT "organization_municipality_id_fkey"
        FOREIGN KEY ("municipality_id") REFERENCES "municipality" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "user" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "first_name" varchar(100) NOT NULL,
    "last_name" varchar(100) NOT NULL,
    "middle_name" varchar(100),
    "birth" date,
    "email" varchar(255) UNIQUE NOT NULL,
    "password_hash" text,
    "tg_username" varchar(64),
    "telegram_user_id" bigint UNIQUE,
    "municipality_id" bigint,
    "organization_id" bigint,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz,
    CONSTRAINT "user_municipality_id_fkey"
        FOREIGN KEY ("municipality_id") REFERENCES "municipality" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "user_organization_id_fkey"
        FOREIGN KEY ("organization_id") REFERENCES "organization" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "role" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" varchar(100) UNIQUE NOT NULL,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz
);

CREATE TABLE "role_user" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" bigint NOT NULL,
    "role_id" bigint NOT NULL,
    "granted_at" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "role_user_user_id_fkey"
        FOREIGN KEY ("user_id") REFERENCES "user" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "role_user_role_id_fkey"
        FOREIGN KEY ("role_id") REFERENCES "role" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "user_discipline" (
    "user_id" bigint NOT NULL,
    "discipline_id" bigint NOT NULL,
    "start_year" smallint,
    PRIMARY KEY ("user_id", "discipline_id"),
    CONSTRAINT "user_discipline_user_id_fkey"
        FOREIGN KEY ("user_id") REFERENCES "user" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "user_discipline_discipline_id_fkey"
        FOREIGN KEY ("discipline_id") REFERENCES "discipline" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "athlete_coach" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "athlete_user_id" bigint NOT NULL,
    "coach_user_id" bigint NOT NULL,
    "discipline_id" bigint NOT NULL,
    "status" varchar(20) NOT NULL DEFAULT 'pending',
    "requested_at" timestamptz NOT NULL DEFAULT now(),
    "confirmed_at" timestamptz,
    "ended_at" timestamptz,
    CONSTRAINT "athlete_coach_athlete_user_id_fkey"
        FOREIGN KEY ("athlete_user_id") REFERENCES "user" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "athlete_coach_coach_user_id_fkey"
        FOREIGN KEY ("coach_user_id") REFERENCES "user" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "athlete_coach_discipline_id_fkey"
        FOREIGN KEY ("discipline_id") REFERENCES "discipline" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "user_rank_discipline" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" bigint NOT NULL,
    "rank_id" bigint NOT NULL,
    "discipline_id" bigint NOT NULL,
    "result_id" bigint,
    "awarded_at" date,
    "expires_at" date,
    "order_number" varchar(100),
    CONSTRAINT "user_rank_discipline_user_id_fkey"
        FOREIGN KEY ("user_id") REFERENCES "user" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "user_rank_discipline_rank_id_fkey"
        FOREIGN KEY ("rank_id") REFERENCES "rank" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "user_rank_discipline_discipline_id_fkey"
        FOREIGN KEY ("discipline_id") REFERENCES "discipline" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "user_judge_category" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" bigint NOT NULL,
    "category_id" bigint NOT NULL,
    "assigned_at" date NOT NULL,
    "expires_at" date,
    "order_number" varchar(100),
    CONSTRAINT "user_judge_category_user_id_fkey"
        FOREIGN KEY ("user_id") REFERENCES "user" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "user_judge_category_category_id_fkey"
        FOREIGN KEY ("category_id") REFERENCES "judge_category" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "anti_doping" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" bigint NOT NULL,
    "url" text,
    "ttl" date,
    "completed_at" date,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz,
    CONSTRAINT "anti_doping_user_id_fkey"
        FOREIGN KEY ("user_id") REFERENCES "user" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "consent_data" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" bigint NOT NULL,
    "consent_data_url" text NOT NULL,
    "status" varchar(20) NOT NULL DEFAULT 'pending',
    "signed_at" timestamptz,
    "legal_representative_name" varchar(250),
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz,
    CONSTRAINT "consent_data_user_id_fkey"
        FOREIGN KEY ("user_id") REFERENCES "user" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE UNIQUE INDEX "role_user_user_id_role_id_idx" ON "role_user" ("user_id", "role_id");

COMMENT ON COLUMN "user"."email" IS 'Email нужен для входа и приглашения. Сравнение без учёта регистра обеспечивается миграцией.';
COMMENT ON COLUMN "user"."password_hash" IS 'NULL для приглашённого аккаунта до завершения регистрации';
COMMENT ON COLUMN "user"."organization_id" IS 'NULL = без организации';
COMMENT ON COLUMN "role"."name" IS 'Спортсмен, тренер, судья, сотрудник федерации';
COMMENT ON COLUMN "athlete_coach"."status" IS 'pending, active, suspended, completed, rejected';
COMMENT ON COLUMN "consent_data"."status" IS 'pending, approved, rejected';
